{"refs":["jobs"],"code":"def solve(facts):
    jobs = facts["jobs"]
    n = len(jobs)
    ids = [j["id"] for j in jobs]
    index = {x: i for i, x in enumerate(ids)}
    pred = []
    for j in jobs:
        mask = 0
        for x in j["predecessors"]:
            mask |= 1 << index[x]
        pred.append(mask)
    full = (1 << n) - 1
    best = None
    def visit(mask, time, order, starts, cost):
        nonlocal best
        if mask == full:
            seq = tuple(ids[i] for i in order)
            key = (cost, time, seq)
            if best is None or key < best[0]:
                best = (key, seq, list(starts), time)
            return
        for i, j in enumerate(jobs):
            bit = 1 << i
            if mask & bit or pred[i] & ~mask:
                continue
            start = max(time, j["release"])
            end = start + j["duration"]
            tardiness = j["weight"] * max(0, end - j["due"])
            visit(mask | bit, end, order + [i], starts + [start], cost + tardiness)
    visit(0, 0, [], [], 0)
    return {"order": list(best[1]), "starts": best[2], "finish": best[3], "weighted_tardiness": best[0][0]}

def check(answer, facts):
    jobs = facts["jobs"]
    n = len(jobs)
    if len(answer["order"]) != n or len(answer["starts"]) != n:
        return False
    by_id = {j["id"]: j for j in jobs}
    if len(set(answer["order"])) != n or any(x not in by_id for x in answer["order"]):
        return False
    pos = {x: i for i, x in enumerate(answer["order"])}
    t = 0
    cost = 0
    for k, x in enumerate(answer["order"]):
        j = by_id[x]
        if any(p not in pos or pos[p] >= k for p in j["predecessors"]):
            return False
        start = max(t, j["release"])
        if answer["starts"][k] != start:
            return False
        t = start + j["duration"]
        cost += j["weight"] * max(0, t - j["due"])
    if answer["finish"] != t or answer["weighted_tardiness"] != cost:
        return False
    # Independently enumerate all feasible orders and compare the optimum key.
    best = None
    ids = [j["id"] for j in jobs]
    idx = {x: i for i, x in enumerate(ids)}
    pred = []
    for j in jobs:
        m = 0
        for p in j["predecessors"]:
            m |= 1 << idx[p]
        pred.append(m)
    full = (1 << n) - 1
    def enumerate_orders(mask, tm, seq, c):
        nonlocal best
        if mask == full:
            key = (c, tm, tuple(seq))
            if best is None or key < best:
                best = key
            return
        for i, j in enumerate(jobs):
            bit = 1 << i
            if not mask & bit and not pred[i] & ~mask:
                end = max(tm, j["release"]) + j["duration"]
                enumerate_orders(mask | bit, end, seq + [j["id"]], c + j["weight"] * max(0, end - j["due"]))
    enumerate_orders(0, 0, [], 0)
    return (cost, t, tuple(answer["order"])) == best"}

